using Lorcaire.Application.Calendar;using Lorcaire.Application.Calendar.DeleteCalendarEvent;using Lorcaire.Application.Calendar.Persistence;using Lorcaire.Application.Calendar.UpdateCalendarEvent;using Lorcaire.Core.Domain.Areas;using Lorcaire.Core.Domain.Calendar;
namespace Lorcaire.Application.Tests.Calendar;
public sealed class ManageCalendarEventHandlersTests{[Fact]public async Task UpdateValidatesTimeline_AndDeleteReportsMissing(){var start=new DateTimeOffset(2026,8,21,10,0,0,TimeSpan.Zero);var x=new CalendarEvent(CalendarEventId.New(),AreaId.New(),"Old",start);var r=new Repo(x);var h=new UpdateCalendarEventHandler(r);await h.HandleAsync(new(x.Id.Value,"New","Desc",start.AddHours(1),start.AddHours(2)));Assert.Equal("New",x.Title);await Assert.ThrowsAsync<ArgumentException>(()=>h.HandleAsync(new(x.Id.Value,"Bad",null,start,start.AddHours(-1))));await new DeleteCalendarEventHandler(r).HandleAsync(x.Id.Value);await Assert.ThrowsAsync<CalendarEventNotFoundException>(()=>new DeleteCalendarEventHandler(r).HandleAsync(x.Id.Value));}private sealed class Repo(params CalendarEvent[]v):ICalendarEventRepository{private readonly Dictionary<CalendarEventId,CalendarEvent>d=v.ToDictionary(x=>x.Id);public Task AddAsync(CalendarEvent x,CancellationToken c=default){d.Add(x.Id,x);return Task.CompletedTask;}public Task<CalendarEvent?>GetByIdAsync(CalendarEventId id,CancellationToken c=default){d.TryGetValue(id,out var x);return Task.FromResult(x);}public Task UpdateAsync(CalendarEvent x,CancellationToken c=default){d[x.Id]=x;return Task.CompletedTask;}public Task<bool>DeleteAsync(CalendarEventId id,CancellationToken c=default)=>Task.FromResult(d.Remove(id));}}
